<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Notification\Message\Domain\ValueObject\MessageRetriesVO;
use Civi\Lughauth\Features\Notification\Message\Domain\ValueObject\Holder\MessageRetriesAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the MessageRetriesAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class MessageRetriesAttributeHolderUnitTest extends TestCase
{
        /**
         * Asserts that the code attribute is not assigned by default
         * and that getRetries returns null on a freshly created holder.
         */
        public function testRetriesNotAssignedByDefault(): void
        {
            // Arrange
            $holder = new ImplWithMessageRetriesAttributeHolderUnitTest();

            // Assert
            $this->assertFalse($holder->isRetriesAssigned());
            $this->assertNull($holder->getRetries());
        }
}
class ImplWithMessageRetriesAttributeHolderUnitTest
{
  use MessageRetriesAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedRetriesRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultRetries();
    }}
